package com.aistock.prediction.portfolioanalysis;
import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;import com.aistock.common.BusinessException;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PortfolioDependencyHttpTest {
 @Test void controlledStatusesBoundedBodyAndNoRedirectOrRetry()throws Exception{
  var calls=new AtomicInteger();var mode=new AtomicInteger(200);var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/internal/v1/test",e->{calls.incrementAndGet();assertEquals("fixture-service",e.getRequestHeaders().getFirst("X-Service-Token"));int status=mode.get();String text=status==200?"{\"code\":\"OK\",\"data\":{\"value\":1}}":status==401?"{\"code\":\"AUTH_REQUIRED\",\"data\":null}":"{\"code\":\"INTERNAL_ERROR\",\"data\":null}";if(status==302)e.getResponseHeaders().set("Location","/redirected");byte[] data=text.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(status,data.length);e.getResponseBody().write(data);e.close();});
  server.createContext("/redirected",e->{calls.addAndGet(100);e.sendResponseHeaders(200,-1);e.close();});server.createContext("/internal/v1/big",e->{byte[] data=new byte[262145];e.sendResponseHeaders(200,data.length);e.getResponseBody().write(data);e.close();});server.start();
  try{var http=new PortfolioDependencyHttp("fixture-service",new ObjectMapper());String base="http://127.0.0.1:"+server.getAddress().getPort();assertEquals(1,http.call(base,"/internal/v1/test",java.util.Map.of("fixture",true),2).path("value").asInt());mode.set(401);assertEquals(401,assertThrows(BusinessException.class,()->http.call(base,"/internal/v1/test",null,2)).status().value());mode.set(302);assertThrows(BusinessException.class,()->http.call(base,"/internal/v1/test",null,2));assertEquals(3,calls.get());mode.set(503);assertThrows(BusinessException.class,()->http.call(base,"/internal/v1/test",null,2));assertEquals(4,calls.get());assertThrows(BusinessException.class,()->http.call(base,"/internal/v1/big",null,2));assertThrows(BusinessException.class,()->new PortfolioDependencyHttp("",new ObjectMapper()).call(base,"/internal/v1/test",null,2));}finally{server.stop(0);}
 }
 @Test void slowChunkedBodyIsCanceledWithinOverallTimeout()throws Exception{
  var executor=Executors.newCachedThreadPool();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(executor);
  server.createContext("/internal/v1/slow",e->{try{e.sendResponseHeaders(200,0);e.getResponseBody().write('{');e.getResponseBody().flush();Thread.sleep(1800);e.getResponseBody().write('}');}catch(Exception ignored){}finally{e.close();}});server.start();
  try{long start=System.nanoTime();assertThrows(BusinessException.class,()->new PortfolioDependencyHttp("fixture",new ObjectMapper()).call("http://127.0.0.1:"+server.getAddress().getPort(),"/internal/v1/slow",null,1));assertTrue(System.nanoTime()-start<TimeUnit.MILLISECONDS.toNanos(1700));}finally{server.stop(0);executor.shutdownNow();}
 }
 @Test void serviceCredentialDenialMalformedJsonAndBrokenBodyAreControlled()throws Exception{
  var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/internal/v1/denied",e->{calls.incrementAndGet();byte[] b="{\"code\":\"INTERNAL_AUTH_REQUIRED\",\"data\":null}".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(401,b.length);e.getResponseBody().write(b);e.close();});
  server.createContext("/internal/v1/malformed",e->{calls.incrementAndGet();byte[] b="not-json".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});
  server.createContext("/internal/v1/broken",e->{calls.incrementAndGet();e.sendResponseHeaders(200,100);e.getResponseBody().write('{');e.getResponseBody().flush();e.close();});server.start();
  try{var http=new PortfolioDependencyHttp("fixture",new ObjectMapper());String base="http://127.0.0.1:"+server.getAddress().getPort();for(String path:new String[]{"denied","malformed","broken"}){var error=assertThrows(BusinessException.class,()->http.call(base,"/internal/v1/"+path,java.util.Map.of("fixture",true),1));assertEquals(503,error.status().value());}assertEquals(3,calls.get());}finally{server.stop(0);}
 }
 @Test void usageHeadersGoOnlyToValuationNotUserSnapshotOrRevision()throws Exception{
  var headers=new java.util.ArrayList<java.util.Map<String,String>>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/internal/v1/",e->{var h=new java.util.HashMap<String,String>();for(var k:java.util.List.of("X-Market-Use-Bundle","X-Market-Use-Owner","X-Market-Use-Purpose","X-Market-Use-Operation","X-Market-Use-Generation")){var v=e.getRequestHeaders().getFirst(k);if(v!=null)h.put(k,v);}headers.add(h);byte[] b="{\"code\":\"OK\",\"data\":{}}".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();
  try{var exec=java.util.UUID.randomUUID().toString();var request=new com.aistock.prediction.marketuse.MarketUseClient.Request(exec,"1",java.util.UUID.randomUUID().toString(),"PORTFOLIO_VALUATION",new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("CURRENT_HEADS",null,null,java.util.List.of("SH600030","SH600276")));var receipt=new com.aistock.prediction.marketuse.MarketUseClient.Receipt(java.util.UUID.randomUUID().toString(),"ACTIVE",java.util.List.of(java.util.UUID.randomUUID().toString(),java.util.UUID.randomUUID().toString()));try(var scope=com.aistock.prediction.marketuse.MarketUseContext.open(request,receipt)){var http=new PortfolioDependencyHttp("fixture",new ObjectMapper());String base="http://127.0.0.1:"+server.getAddress().getPort();for(var path:java.util.List.of("/internal/v1/positions/snapshot","/internal/v1/market/valuation-quotes","/internal/v1/positions/revision"))http.call(base,path,java.util.Map.of("fixture",true),2);}assertEquals(3,headers.size());assertTrue(headers.get(0).isEmpty());assertEquals(5,headers.get(1).size());assertEquals(exec,headers.get(1).get("X-Market-Use-Operation"));assertTrue(headers.get(2).isEmpty());assertTrue(com.aistock.prediction.marketuse.MarketUseContext.headers().isEmpty());}finally{server.stop(0);}
 }

}
